package dev.industrialtechnology.railway;
import java.util.*;import net.minecraft.tileentity.TileEntity;import net.minecraft.inventory.*;import net.minecraft.item.ItemStack;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.entity.item.EntityItem;import net.minecraft.nbt.*;import net.minecraft.util.AxisAlignedBB;import net.minecraftforge.common.util.ForgeDirection;import cofh.api.energy.*;import dev.industrialtechnology.expansion.ExpansionConfig;
public final class TileRailStation extends TileEntity implements IInventory,IEnergyReceiver {
 private final ItemStack[] items=new ItemStack[9];public int energy;public long transferred;public String state="NO STOPPED VEHICLE",vehicle="-";public int free;private long tick=Long.MIN_VALUE;private int used;private EntityRollingStock current;
 public int kind(){return getBlockType() instanceof BlockRailStation?((BlockRailStation)getBlockType()).kind:0;}
 @Override public void updateEntity(){if(worldObj.isRemote)return;if(ticks()%10==0||current==null||current.isDead||current.getDistanceSq(xCoord+.5,yCoord+.5,zCoord+.5)>100){current=null;for(Object o:worldObj.getEntitiesWithinAABB(EntityRollingStock.class,AxisAlignedBB.getBoundingBox(xCoord-7,yCoord-3,zCoord-7,xCoord+8,yCoord+5,zCoord+8))){EntityRollingStock e=(EntityRollingStock)o;if(e.speed<.001&&(kind()==0?e.stock.electric():e.stock==StockType.FREIGHT)){current=e;break;}}}state="NO STOPPED VEHICLE";vehicle="-";free=0;int budget=ExpansionConfig.transfer;
  if(kind()!=0)for(ForgeDirection d:ForgeDirection.VALID_DIRECTIONS){int x=xCoord+d.offsetX,z=zCoord+d.offsetZ;if(!worldObj.getChunkProvider().chunkExists(x>>4,z>>4))continue;TileEntity other=worldObj.getTileEntity(x,yCoord+d.offsetY,z);if(!(other instanceof IInventory)||other instanceof TileRailStation)continue;if(kind()==1)budget-=InventoryTransfer.move((IInventory)other,this,d.getOpposite().ordinal(),d.ordinal(),budget);else budget-=InventoryTransfer.move(this,(IInventory)other,d.ordinal(),d.getOpposite().ordinal(),budget);if(budget<=0)break;}
  if(current==null||current.speed>=.001)return;vehicle=current.stock.title;if(kind()==0){int n=current.charge(Math.min(energy,ExpansionConfig.chargeRate),false);energy-=n;transferred+=n;state=n>0?"CHARGING":energy==0?"NEED RF":current.energy>=current.capacity()?"FULL":"INPUT LIMIT";if(n>0)markDirty();return;}
  int moved=0;for(int logical=0;logical<3;logical++){free+=current.cargo.capacity(logical)-current.cargo.count(logical);if(moved>=ExpansionConfig.transfer)continue;if(kind()==1){for(int slot=0;slot<9;slot++){ItemStack item=items[slot];int n=current.cargo.insert(logical,item,ExpansionConfig.transfer-moved,false);if(n>0){decrStackSize(slot,n);moved+=n;}if(moved>=ExpansionConfig.transfer)break;}}else{ItemStack item=current.cargo.extract(logical,ExpansionConfig.transfer-moved,true);if(item!=null){int n=InventoryTransfer.insert(this,item,0,item.stackSize);current.cargo.extract(logical,n,false);moved+=n;}}}transferred+=moved;state=moved>0?kind()==1?"LOADING":"UNLOADING":"WAITING / FULL";if(moved>0)markDirty();
 }
 private long ticks(){return worldObj.getTotalWorldTime();}@Override public int receiveEnergy(ForgeDirection side,int max,boolean sim){if(worldObj==null||worldObj.isRemote||kind()!=0||max<=0)return 0;long now=ticks();if(tick!=now){tick=now;used=0;}int n=Math.max(0,Math.min(max,Math.min(2000000-energy,ExpansionConfig.chargeRate-used)));if(!sim){used+=n;energy+=n;if(n>0)markDirty();}return n;}@Override public boolean canConnectEnergy(ForgeDirection d){return kind()==0&&d!=ForgeDirection.UNKNOWN;}@Override public int getEnergyStored(ForgeDirection d){return energy;}@Override public int getMaxEnergyStored(ForgeDirection d){return kind()==0?2000000:0;}
 public boolean usable(EntityPlayer p){return !isInvalid()&&p.worldObj==worldObj&&p.getDistanceSq(xCoord+.5,yCoord+.5,zCoord+.5)<=64&&worldObj.getTileEntity(xCoord,yCoord,zCoord)==this;}
 @Override public int getSizeInventory(){return 9;}@Override public ItemStack getStackInSlot(int i){return i<0||i>=9?null:items[i];}@Override public ItemStack decrStackSize(int i,int n){ItemStack old=getStackInSlot(i);if(old==null||n<=0)return null;ItemStack out=old.splitStack(Math.min(n,old.stackSize));if(old.stackSize<=0)items[i]=null;markDirty();return out;}@Override public ItemStack getStackInSlotOnClosing(int i){ItemStack s=getStackInSlot(i);items[i]=null;return s;}@Override public void setInventorySlotContents(int i,ItemStack s){if(i<0||i>=9)return;items[i]=s;if(s!=null)s.stackSize=Math.min(s.stackSize,Math.min(64,s.getMaxStackSize()));markDirty();}@Override public String getInventoryName(){return "Rail Station";}@Override public boolean hasCustomInventoryName(){return false;}@Override public int getInventoryStackLimit(){return 64;}@Override public boolean isUseableByPlayer(EntityPlayer p){return usable(p);}@Override public void openInventory(){}@Override public void closeInventory(){}@Override public boolean isItemValidForSlot(int i,ItemStack s){return kind()!=0;}
 @Override public void writeToNBT(NBTTagCompound n){super.writeToNBT(n);n.setInteger("RF",energy);n.setLong("Transferred",transferred);NBTTagList l=new NBTTagList();for(int i=0;i<9;i++)if(items[i]!=null){NBTTagCompound t=new NBTTagCompound();items[i].writeToNBT(t);t.setByte("Slot",(byte)i);l.appendTag(t);}n.setTag("Items",l);}@Override public void readFromNBT(NBTTagCompound n){super.readFromNBT(n);energy=Math.max(0,Math.min(2000000,n.getInteger("RF")));transferred=Math.max(0,n.getLong("Transferred"));Arrays.fill(items,null);NBTTagList l=n.getTagList("Items",10);for(int i=0;i<Math.min(9,l.tagCount());i++){NBTTagCompound t=l.getCompoundTagAt(i);int slot=t.getByte("Slot")&255;if(slot<9){ItemStack s=ItemStack.loadItemStackFromNBT(t);if(s!=null){s.stackSize=Math.min(s.stackSize,Math.min(64,s.getMaxStackSize()));items[slot]=s;}}}}
 public NBTTagCompound snapshot(){NBTTagCompound n=new NBTTagCompound();n.setString("Title",getBlockType().getLocalizedName());n.setString("Status",state);n.setString("Vehicle",vehicle);n.setInteger("RF",energy);n.setLong("Transferred",transferred);n.setInteger("Free",free);n.setInteger("TrainRF",current!=null&&current.stock.electric()?current.energy:0);n.setInteger("TrainCapacity",current!=null&&current.stock.electric()?current.capacity():0);return n;}
 public void drop(){for(int i=0;i<9;i++){ItemStack s=items[i];items[i]=null;if(s!=null)worldObj.spawnEntityInWorld(new EntityItem(worldObj,xCoord+.5,yCoord+.5,zCoord+.5,s));}}
}
